23	}
24	
25	type Stations map[string]*Station
26	
27	var ErrUnknownStation = errors.New("unknown station")
28	
29	func (s Stations) Get(id string) (*Station, error) {
30		st, ok := s[id]
31		if !ok {
32			return nil, fmt.Errorf("%w: %q (known: %s)", ErrUnknownStation, id, strings.Join(s.IDs(), ", "))
33		}
34		return st, nil
35	}
36	
37	func (s Stations) IDs() []string {
38		ids := make([]string, 0, len(s))
39		for id := range s {
40			ids = append(ids, id)
41		}
42		sort.Strings(ids)
43		return ids
44	}
45	
46	func LoadDir(dir string) (Stations, error) {
47		sf, err := os.Open(filepath.Join(dir, "stations.csv"))
48		if err != nil {
49			return nil, err
50		}
51		defer sf.Close()
52		stations, err := ReadStations(sf, "stations.csv")
53		if err != nil {
54			return nil, err
55		}
56	
57		cf, err := os.Open(filepath.Join(dir, "constituents.csv"))
58		if err != nil {
59			return nil, err
60		}
61		defer cf.Close()
62		if err := ReadConstituents(cf, "constituents.csv", stations); err != nil {
63			return nil, err
64		}
65		return stations, nil
66	}
67	
68	func ReadStations(r io.Reader, name string) (Stations, error) {
69		stations := Stations{}
70		err := eachRow(r, name, 4, func(line int, rec []string) error {
71			loc, err := time.LoadLocation(rec[2])
72			if err != nil {
73				return fmt.Errorf("%s:%d: timezone %q: %w", name, line, rec[2], err)
74			}
75			datum, err := strconv.ParseFloat(rec[3], 64)
76			if err != nil {
77				return fmt.Errorf("%s:%d: datum %q is not a number", name, line, rec[3])
78			}
79			stations[rec[0]] = &Station{ID: rec[0], Name: rec[1], Location: loc, Datum: datum}
80			return nil
81		})
82		return stations, err
83	}
84	
85	func ReadConstituents(r io.Reader, name string, stations Stations) error {
86		return eachRow(r, name, 4, func(line int, rec []string) error {
87			st, ok := stations[rec[0]]
88			if !ok {
89				return fmt.Errorf("%s:%d: %w %q", name, line, ErrUnknownStation, rec[0])
90			}
91			speed, ok := Speeds[rec[1]]
92			if !ok {
93				return nil
94			}
95			amp, err := strconv.ParseFloat(rec[2], 64)
96			if err != nil {
97				return fmt.Errorf("%s:%d: amplitude %q is not a number", name, line, rec[2])
98			}
99			phase, err := strconv.ParseFloat(rec[3], 64)
100			if err != nil {
101				return fmt.Errorf("%s:%d: phase %q is not a number", name, line, rec[3])
102			}
103			st.Constituents = append(st.Constituents, Constituent{Name: rec[1], Amplitude: amp, Phase: phase, Speed: speed})
104			return nil
105		})
106	}
107	
108	func eachRow(r io.Reader, name string, fields int, fn func(line int, rec []string) error) error {
109		cr := csv.NewReader(r)
110		cr.FieldsPerRecord = fields
111		cr.TrimLeadingSpace = true
112		if _, err := cr.Read(); err != nil {
113			return fmt.Errorf("%s: reading header: %w", name, err)
114		}
115		for {
116			rec, err := cr.Read()
117			if err == io.EOF {
118				return nil
119			}
120			if err != nil {
121				return fmt.Errorf("%s: %w", name, err)
122			}
123			line, _ := cr.FieldPos(0)
124			if err := fn(line, rec); err != nil {
125				return err
126			}
127		}
128	}
